"""patch_panel_v2.py — PANEL-V2: scrubbable fields + one-click fit (2026-07-03).

The position/orientation sliders spanned the whole map (1 slider px = meters)
— useless for fine work. Replaced by pro-tool scrub fields: drag horizontally
ON the number (Shift = x0.1 fine, Ctrl = x10 coarse), plain click = type the
exact value, arrows = step. And the panel becomes a Position Lab: the
"⌖ Fit ypr+fov" button re-aims orientation+fov on the cam's markings with
xyz LOCKED at the CURRENT (unsaved) values — server-side fit_minimal, dry:
review the residuals, scrub xyz again if the worst is high, re-fit, Save when
happy. The exact Kayak/Landing Gear workflow, without the terminal.

Headless-tested live: scrub gain exact, click-to-type, fit on Gas Station
(Chase) (S) returns worst 0.95' and the known-good yaw. Zero JS errors.
Independent of MARKING-V1 (applies before or after it).
Idempotent. Backups: .bak_panel. Restart server + hard refresh after.
"""
import shutil, sys

# ---- server.py: /api/fit_minimal endpoint ----
P = 'tools/server.py'
s = open(P).read()
if 'PANEL-V2' in s:
    print('server: deja patche')
else:
    shutil.copy(P, P + '.bak_panel')
    anchor = "        elif path == '/api/triage':"
    assert anchor in s, 'anchor server'
    s = s.replace(anchor, "        elif path == '/api/fit_minimal':\n            # [PANEL-V2] fit ypr(+roll)+fov with xyz LOCKED at the CLIENT's\n            # (possibly unsaved) values. Returns the fitted pose WITHOUT\n            # writing — the user reviews residuals then Saves normally.\n            cam_name = unquote(qs.get('cam', [''])[0])\n            if cam_name not in md.cameras:\n                self.send_json({'error': 'unknown cam'}, 404); return\n            try:\n                cx = float(qs.get('x', [''])[0]); cy = float(qs.get('y', [''])[0])\n                cz = float(qs.get('z', [''])[0])\n            except (ValueError, IndexError):\n                self.send_json({'error': 'x, y, z required'}, 400); return\n            solve_roll = qs.get('roll', ['0'])[0] == '1'\n            sys.path.insert(0, TOOL_DIR)\n            import fit_minimal as fm\n            obs = fm.gather_obs(cam_name)\n            if len(obs) < 2:\n                self.send_json({'error': f'only {len(obs)} triangulated marking(s) — need >= 2'}, 400)\n                return\n            saved = dict(md.cameras[cam_name])\n            try:\n                st = dict(saved)\n                st['xyz'] = [cx, cy, cz]\n                # init ypr/fov from client too when provided\n                try:\n                    st['ypr'] = [float(qs.get('yaw', [saved['ypr'][0]])[0]),\n                                 float(qs.get('pitch', [saved['ypr'][1]])[0]),\n                                 float(qs.get('rollv', [saved['ypr'][2]])[0])]\n                except (ValueError, TypeError):\n                    pass\n                md.cameras[cam_name] = st\n                ypr, fov_val, res = fm.fit(cam_name, obs, solve_roll)\n                # effective hfov at the fitted state\n                _idx, _ = fm.fov_slot(md.cameras[cam_name])\n                cam_fit = fm.make_cam(cam_name, ypr, fov_val)\n                self.send_json({'ok': True,\n                                'ypr': [round(float(v), 4) for v in ypr],\n                                'hfov': round(float(cam_fit.hfov), 4),\n                                'residuals': sorted([{'lm': ln, 'arcmin': (None if r == float('inf') else round(r, 2))}\n                                                     for r, ln in res], key=lambda x: -(x['arcmin'] or 1e9)),\n                                'n_obs': len(obs)})\n            finally:\n                md.cameras[cam_name] = saved\n                try:\n                    ml.get_camera.cache_clear()\n                except Exception:\n                    pass\n\n" + anchor, 1)
    open(P, 'w').write(s)
    print('tools/server.py: /api/fit_minimal ajoute')

# ---- calib.html: bouton + css + js ----
P = 'tools/calib.html'
s = open(P).read()
if 'PANEL-V2' in s:
    print('calib: deja patche'); sys.exit(0)
shutil.copy(P, P + '.bak_panel')
hfov_row = '      <div class="sl-row"><span class="sl-lbl">hFOV</span><input type="range" id="sl-hfov" min="10" max="130" step="0.01"><input class="num" id="num-hfov" type="number" step="0.01"></div>'
assert hfov_row in s, 'anchor hfov row'
s = s.replace(hfov_row, hfov_row + '\n      <!-- [PANEL-V2] -->\n      <div style="display:flex;gap:6px;margin-top:8px">\n        <button id="pv2-fit" title="fit yaw/pitch/fov on this cam\'s markings, xyz locked at the values above (dry — review then Save)"\n          style="flex:1;font-family:var(--mono,monospace);font-size:10px;padding:5px 8px;background:#ffffff10;\n          border:1px solid var(--border,#333);color:var(--text,#ddd);border-radius:5px;cursor:pointer">⌖ Fit ypr+fov (xyz locked)</button>\n        <button id="pv2-fit-roll" title="same, also freeing roll (soft prior at 0)"\n          style="font-family:var(--mono,monospace);font-size:10px;padding:5px 8px;background:#ffffff10;\n          border:1px solid var(--border,#333);color:var(--mid,#999);border-radius:5px;cursor:pointer">+roll</button>\n      </div>\n      <div id="pv2-fit-out" style="display:none;font-family:var(--mono,monospace);font-size:10px;\n        color:var(--mid,#999);margin-top:5px;line-height:1.5"></div>', 1)
assert '</style>' in s
s = s.replace('</style>', '\n/* [PANEL-V2] sliders -> scrubbable value fields */\n.sl-row input[type=range]{display:none}\n.sl-row .num{width:100%;cursor:ew-resize;font-size:13px;padding:6px 10px;text-align:right;\n  -moz-appearance:textfield}\n.sl-row .num::-webkit-outer-spin-button,.sl-row .num::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}\n.sl-row .num:focus{cursor:text;border-color:var(--green,#4ade80)}\n.sl-row .num.pv2-scrubbing{border-color:var(--green,#4ade80);color:var(--green,#4ade80)}\n' + '</style>', 1)
i = s.rindex('</body>')
s = s[:i] + '\n<script>\n// ══ [PANEL-V2] scrubbable param fields + one-click orientation fit ══\n// Sliders spanned the whole map (1 slider px = meters): useless for fine\n// work. Pro-tool pattern instead: drag horizontally ON the number\n// (Shift = x0.1 fine, Ctrl = x10 coarse), click = type exact, arrows = step.\n// The "Fit ypr+fov" button turns the panel into a Position Lab: scrub xyz,\n// one click re-aims orientation+fov on the markings (server-side\n// fit_minimal, xyz locked at the CURRENT unsaved values, dry — then Save).\n(() => {\n  const GAIN = { x: 0.25, y: 0.25, z: 0.1, yaw: 0.02, pitch: 0.02, roll: 0.02, hfov: 0.02 };\n  const DEC  = { x: 2, y: 2, z: 2, yaw: 3, pitch: 3, roll: 3, hfov: 3 };\n  let scrub = null;\n\n  Object.keys(NUM_IDS).forEach(key => {\n    const el = document.getElementById(NUM_IDS[key]);\n    el.addEventListener(\'mousedown\', e => {\n      if (document.activeElement === el) return;   // typing mode\n      scrub = { key, el, x0: e.clientX, v0: parseFloat(el.value) || 0, moved: false };\n      e.preventDefault();\n    });\n  });\n  window.addEventListener(\'mousemove\', e => {\n    if (!scrub) return;\n    const dx = e.clientX - scrub.x0;\n    if (!scrub.moved && Math.abs(dx) < 3) return;\n    if (!scrub.moved) { scrub.moved = true; scrub.el.classList.add(\'pv2-scrubbing\'); scrub.el.blur(); }\n    const g = GAIN[scrub.key] * (e.shiftKey ? 0.1 : 1) * (e.ctrlKey || e.metaKey ? 10 : 1);\n    const v = scrub.v0 + dx * g;\n    onParam(scrub.key, v.toFixed(DEC[scrub.key]));\n  });\n  window.addEventListener(\'mouseup\', () => {\n    if (!scrub) return;\n    const s0 = scrub; scrub = null;\n    s0.el.classList.remove(\'pv2-scrubbing\');\n    if (!s0.moved) { s0.el.focus(); s0.el.select(); }   // plain click = type\n  });\n\n  // ── one-click fit ──\n  const out = document.getElementById(\'pv2-fit-out\');\n  async function runFit(withRoll) {\n    if (!currentCam) return;\n    out.style.display = \'block\';\n    out.textContent = \'fitting…\';\n    const q = new URLSearchParams({\n      cam: currentCam, x: params.x, y: params.y, z: params.z,\n      yaw: params.yaw, pitch: params.pitch, rollv: params.roll,\n      roll: withRoll ? \'1\' : \'0\'\n    });\n    let d;\n    try { d = await fetch(\'/api/fit_minimal?\' + q).then(r => r.json()); }\n    catch (err) { out.textContent = \'fit failed: \' + err; return; }\n    if (!d.ok) { out.textContent = d.error || \'fit failed\'; return; }\n    onParam(\'yaw\', d.ypr[0]); onParam(\'pitch\', d.ypr[1]); onParam(\'roll\', d.ypr[2]);\n    onParam(\'hfov\', d.hfov);\n    const worst = d.residuals[0];\n    const lines = d.residuals.slice(0, 4).map(r =>\n      (r.arcmin === null ? \'no-proj\' : r.arcmin + "\'") + \' \' + r.lm).join(\'<br>\');\n    const w = worst && worst.arcmin !== null ? worst.arcmin : Infinity;\n    const col = w < 2 ? \'#4ade80\' : w < 8 ? \'#f59e0b\' : \'#f87171\';\n    out.innerHTML = \'<span style="color:\' + col + \'">fit on \' + d.n_obs + \' obs — worst \' +\n      (worst ? (worst.arcmin === null ? \'no-proj\' : worst.arcmin + "\'") : \'?\') + \'</span>\' +\n      (w >= 5 ? \' <span style="color:var(--mid)">(xyz off? scrub &amp; re-fit)</span>\' : \'\') +\n      \'<br>\' + lines;\n    window._pv2LastFit = d;   // test hook\n  }\n  document.getElementById(\'pv2-fit\').addEventListener(\'click\', () => runFit(false));\n  document.getElementById(\'pv2-fit-roll\').addEventListener(\'click\', () => runFit(true));\n  console.log(\'[PANEL-V2] scrub fields + fit button active\');\n})();\n</script>\n' + s[i:]
open(P, 'w').write(s)
print('tools/calib.html: scrub fields + fit button')
print('PANEL-V2 applique. Redemarre le serveur + hard refresh.')
